namespace InventoryApp.Services;

public record EquipmentItem(int Id, string Name, string Location, DateOnly LastInspected);

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate network/database latency
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new(1, "Forklift A", "Warehouse 1", new DateOnly(2026, 6, 15)),
            new(2, "Conveyor Belt B", "Warehouse 2", new DateOnly(2026, 5, 20)),
            new(3, "Hydraulic Press C", "Factory Floor", new DateOnly(2026, 4, 10)),
            new(4, "CNC Lathe D", "Machine Shop", new DateOnly(2026, 3, 28)),
            new(5, "Welding Station E", "Assembly Bay", new DateOnly(2026, 6, 1)),
            new(6, "Air Compressor F", "Utility Room", new DateOnly(2026, 2, 14)),
            new(7, "Overhead Crane G", "Loading Dock", new DateOnly(2026, 1, 30)),
            new(8, "Pallet Jack H", "Warehouse 1", new DateOnly(2026, 6, 22)),
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@implements IDisposable
@inject EquipmentService EquipmentSvc
@inject PersistentComponentState ApplicationState

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (equipment is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in equipment)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToString("yyyy-MM-dd")</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? equipment;
    private PersistingComponentStateSubscription persistingSubscription;

    protected override async Task OnInitializedAsync()
    {
        persistingSubscription = ApplicationState.RegisterOnPersisting(PersistData);

        if (!ApplicationState.TryTakeFromJson<List<EquipmentItem>>("equipment", out var restored))
        {
            // First render (prerender): fetch from service
            equipment = await EquipmentSvc.GetEquipmentAsync();
        }
        else
        {
            // Interactive render: reuse persisted data — no second fetch
            equipment = restored;
        }
    }

    private Task PersistData()
    {
        ApplicationState.PersistAsJson("equipment", equipment);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        persistingSubscription.Dispose();
    }
}

